import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();

        do {
            int d = n % 10;
            if (d >= 5) {
                System.out.print("-O|");
            } else {
                System.out.print("O-|");
            }
            d %= 5;
            for (int i = 0; i < d; i++) {
                System.out.print("O");
            }
            System.out.print("-");
            for (int i = 4 - d; i > 0; i--) {
                System.out.print("O");
            }
            System.out.println();
            n /= 10;
        } while (n > 0);
    }
}

